"""Read the small configuration subset that affects listing defaults."""
import ast
import os
import re


def _value(raw):
    raw = raw.split("#", 1)[0].strip()
    if not raw:
        return None
    if raw.startswith('"') or raw.startswith("'"):
        try:
            return ast.literal_eval(raw)
        except (ValueError, SyntaxError):
            return raw.strip('"\'')
    if raw.lower() in ('true', 'false'):
        return raw.lower() == 'true'
    if raw.startswith('[') and raw.endswith(']'):
        body = raw[1:-1].strip()
        if not body:
            return []
        vals = []
        for item in re.findall(r'''(?:"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|[^,]+)''', body):
            v = _value(item.strip())
            if v is not None:
                vals.append(v)
        return vals
    try:
        return int(raw)
    except ValueError:
        try:
            return float(raw)
        except ValueError:
            return raw


def read_toml(path):
    result = {}
    try:
        with open(path, encoding='utf-8') as stream:
            lines = iter(stream)
            section = result
            for line in lines:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                m = re.fullmatch(r'\[([^]]+)\]', line)
                if m:
                    section = result
                    for part in m.group(1).split('.'):
                        section = section.setdefault(part, {})
                    continue
                if '=' not in line:
                    continue
                key, raw = line.split('=', 1)
                raw = raw.strip()
                if raw.startswith('[') and ']' not in raw:
                    chunks = [raw]
                    for more in lines:
                        chunks.append(more.strip())
                        if ']' in more:
                            break
                    raw = ' '.join(chunks)
                section[key.strip()] = _value(raw)
    except (OSError, UnicodeError):
        return {}
    return result


def _merge(base, overlay):
    for key, value in overlay.items():
        if isinstance(value, dict) and isinstance(base.get(key), dict):
            _merge(base[key], value)
        else:
            base[key] = value
    return base


def config_for_listing():
    try:
        from configcmd import paths
        _, global_path = paths()
    except Exception:
        global_path = os.path.join(os.path.expanduser('~'), '.config', 'lla', 'config.toml')
    config = read_toml(global_path)
    directory = os.getcwd()
    while True:
        profile = os.path.join(directory, '.lla.toml')
        if os.path.isfile(profile):
